int maxDegree(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;

    std::vector<int> degrees(N, 0);

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        int deg = 0;
        auto row = A.data() + i * N;
        for (size_t j = 0; j < N; ++j) deg += row[j];
        degrees[i] = deg;
    });

    return *std::max_element(degrees.begin(), degrees.end());
}

