        uint8_t expected = 0;
        if (!visited[i].compare_exchange_strong(expected, 1, std::memory_order_acq_rel))
            return;

        components.fetch_add(1, std::memory_order_relaxed);

        std::vector<size_t> stack;
        stack.push_back(i);

        while (!stack.empty()) {
            size_t u = stack.back();
